INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000277',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the German education system at B2","Use Bildungssystem vocabulary","Talk about Germany''s tiered school system and PISA"],"explanation":{"intro":"Education system vocabulary covers Germany''s school structure, dual vocational training, and educational debates at B2.","culturalNote":"Deutsches Bildungssystem: Grundschule (primary — 4 years), then tripartite system: Hauptschule (vocational path), Realschule (intermediate), Gymnasium (academic — Abitur for university). Gesamtschule (comprehensive school — less common). Dual System (duales Ausbildungssystem — vocational training combining firm + Berufsschule — lauded globally). PISA-Schock (2001 — Germany scored poorly, sparked reform). Schulsystem Ländersache (education is a state matter — Kulturhoheit der Länder). KMK (Kultusministerkonferenz — coordination). Key challenges: Lehrermangel (teacher shortage), Digitalisierung, Bildungsungleichheit."},"examples":[{"german":"Das dreigliedrige Schulsystem Deutschlands wird für seine frühzeitige Selektion kritisiert: Die Empfehlung zum weiterführenden Schultyp nach der Grundschule korreliert stark mit dem sozialen Hintergrund der Schülerinnen und Schüler.","english":"Germany''s tripartite school system is criticised for its early selection: the recommendation for the type of secondary school after primary school correlates strongly with the social background of the pupils."},{"german":"Das duale Ausbildungssystem ist ein weltweit beachtetes Modell, das betriebspraktische Ausbildung mit schultheoretischer Unterweisung verbindet und Jugendarbeitslosigkeit traditionell gering hält.","english":"The dual vocational training system is a globally respected model that combines practical firm-based training with theoretical school-based instruction and has traditionally kept youth unemployment low."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s school system, dual training, and PISA at B2."}}',
'{"items":[{"word":"dreigliedrig","translation":"tripartite","pronunciation":"DRY-glee-drikh","example":"Dreigliedriges Schulsystem."},{"word":"die Selektion","translation":"selection","pronunciation":"dee zeh-lek-TSYOHN","example":"Frühzeitige Selektion."},{"word":"die Empfehlung","translation":"recommendation","pronunciation":"dee em-PFAY-loong","example":"Empfehlung zum Schultyp."},{"word":"korrelieren mit","translation":"to correlate with","pronunciation":"ko-reh-LEER-en mit","example":"Mit dem sozialen Hintergrund korrelieren."},{"word":"betriebspraktisch","translation":"firm-based/practical","pronunciation":"beh-TREEPS-prak-tish","example":"Betriebspraktische Ausbildung."},{"word":"beachtet","translation":"respected/noted","pronunciation":"beh-AKH-tet","example":"Weltweit beachtet."}]}',
'{"title":"Etwas korreliert stark mit X — correlates strongly with X (statistical/social science relationship)","pattern":"etwas korreliert (stark) mit X = something correlates (strongly) with X (korrelieren = to correlate — borrowed from English; with mit + dative; adverb for strength: stark/schwach/positiv/negativ)","explanation":"Korrelieren mit = to correlate with (statistical or social relationship, not necessarily causal). Korreliert stark mit dem sozialen Hintergrund = correlates strongly with social background. Note: correlation ≠ causation (Korrelation ≠ Kausalität). Common in academic/social science discourse. Other strengths: schwach korrelieren (to correlate weakly), positiv/negativ korrelieren (to correlate positively/negatively). Compare: zusammenhängen mit (to be correlated with — more colloquial), in Zusammenhang stehen mit (to be in correlation with — more formal), abhängen von (to depend on — implies directionality).","examples":[{"sentence":"Einkommen korreliert stark mit Bildungsabschluss.","translation":"Income correlates strongly with educational attainment."},{"sentence":"Die Variablen korrelieren positiv miteinander.","translation":"The variables correlate positively with each other."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Dreigliedrig'' means?","options":["tripartite","three-tiered","three-part","trilateral"],"correctAnswer":"tripartite"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Germany''s tripartite school system is criticised for its early selection: the recommendation for the type of secondary school after primary school correlates strongly with the social background of the pupils.","options":["Das dreigliedrige Schulsystem Deutschlands wird für seine frühzeitige Selektion kritisiert: Die Empfehlung zum weiterführenden Schultyp nach der Grundschule korreliert stark mit dem sozialen Hintergrund der Schülerinnen und Schüler.","Das deutsche Schulsystem sortiert Schüler zu früh nach ihren Fähigkeiten.","Die Schulwahl nach der Grundschule hängt stark vom sozialen Status der Eltern ab.","Deutschland selektiert Schüler früher als die meisten anderen Länder."],"correctAnswer":"Das dreigliedrige Schulsystem Deutschlands wird für seine frühzeitige Selektion kritisiert: Die Empfehlung zum weiterführenden Schultyp nach der Grundschule korreliert stark mit dem sozialen Hintergrund der Schülerinnen und Schüler."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Einkommen korreliert stark mit ___.","options":["Bildungsabschluss","Intelligenz","Erfolg","Leistung"],"correctAnswer":"Bildungsabschluss"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The variables correlate positively with each other","wordBankItems":["Die","Variablen","korrelieren","positiv","miteinander","."],"correctAnswer":"Die Variablen korrelieren positiv miteinander ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Selektion'' means?","options":["selection","sorting","streaming","placement"],"correctAnswer":"selection"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000278',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss higher education and research at B2","Use Hochschule vocabulary","Talk about German universities, the Exzellenzinitiative, and research culture"],"explanation":{"intro":"Higher education vocabulary covers German university types, research excellence, and academic culture at B2.","culturalNote":"Hochschule und Forschung: Types: Universität (research university), Fachhochschule/HAW (applied university of applied sciences), Technische Universität (TU). Key: Humboldt-Prinzip (research and teaching unity — Wilhelm von Humboldt, 1810 — foundational idea of German university). Exzellenzinitiative/Exzellenzstrategie (excellence initiative — funding elite universities: LMU Munich, TU Munich, Heidelberg). Akkreditierung (accreditation). Research bodies: DFG (Deutsche Forschungsgemeinschaft — national research funder), Max-Planck-Gesellschaft (basic research), Fraunhofer (applied research), Helmholtz (large-scale infrastructure). BAföG (student financial aid). Internationalisierung."},"examples":[{"german":"Das Humboldtsche Bildungsideal, das Forschung und Lehre als untrennbare Einheit begreift, prägt noch heute das Selbstverständnis der deutschen Universitäten, auch wenn wirtschaftlicher Druck und Massenbetrieb es faktisch herausfordern.","english":"The Humboldtian educational ideal, which conceives of research and teaching as an inseparable unity, still shapes the self-understanding of German universities today, even though economic pressure and mass operations factually challenge it."},{"german":"Die Exzellenzstrategie hat eine Hierarchisierung des deutschen Hochschulwesens vorangetrieben, die eine kleine Gruppe forschungsstarker Universitäten besonders fördert — auf Kosten einer breiteren Grundfinanzierung des Systems.","english":"The excellence strategy has driven a hierarchisation of the German higher education system that particularly promotes a small group of research-strong universities — at the cost of broader basic funding for the system."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss German universities, the Humboldtian ideal, and the Exzellenzstrategie at B2."}}',
'{"items":[{"word":"das Selbstverständnis","translation":"self-understanding/self-concept","pronunciation":"dahs ZELPST-fer-shten-nis","example":"Selbstverständnis der Universitäten."},{"word":"faktisch","translation":"factually/in practice","pronunciation":"FAK-tish","example":"Faktisch herausfordern."},{"word":"die Hierarchisierung","translation":"hierarchisation","pronunciation":"dee hee-er-ar-khee-ZEE-roong","example":"Hierarchisierung vorantreiben."},{"word":"forschungsstark","translation":"research-strong","pronunciation":"FOR-shoonks-shtark","example":"Forschungsstarke Universitäten."},{"word":"auf Kosten + genitive","translation":"at the cost of","pronunciation":"owf KOS-ten","example":"Auf Kosten der Breite."},{"word":"die Grundfinanzierung","translation":"basic funding","pronunciation":"dee GROONT-fi-nan-TSEER-oong","example":"Grundfinanzierung des Systems."}]}',
'{"title":"Auf Kosten + genitive — at the cost of (prepositional phrase indicating a trade-off)","pattern":"auf Kosten + genitive = at the cost of, at the expense of (fixed phrase: auf Kosten always takes genitive of what is sacrificed or diminished)","explanation":"Auf Kosten + genitive = at the cost of, at the expense of. Auf Kosten einer breiteren Grundfinanzierung = at the cost of broader basic funding. Fixed phrase (auf Kosten) — always takes genitive. Used to mark a trade-off: X is promoted auf Kosten Y (at the expense of Y). Compare: auf Kosten von + plural (at the cost of — when followed by a name or plural: auf Kosten von Studierenden — at students'' expense), zulasten von (at the expense of — more formal, often in policy), zum Nachteil von (to the detriment of — slightly more neutral).","examples":[{"sentence":"Der schnelle Ausbau erfolgte auf Kosten der Qualität.","translation":"The rapid expansion came at the cost of quality."},{"sentence":"Die Reform wurde auf Kosten der älteren Mitarbeiter durchgesetzt.","translation":"The reform was pushed through at the cost of older employees."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Faktisch'' means?","options":["factually/in practice","effectively","actually","de facto"],"correctAnswer":"factually/in practice"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The Humboldtian educational ideal, which conceives of research and teaching as an inseparable unity, still shapes the self-understanding of German universities today, even though economic pressure and mass operations factually challenge it.","options":["Das Humboldtsche Bildungsideal, das Forschung und Lehre als untrennbare Einheit begreift, prägt noch heute das Selbstverständnis der deutschen Universitäten, auch wenn wirtschaftlicher Druck und Massenbetrieb es faktisch herausfordern.","Das Humboldtsche Ideal verbindet Forschung und Lehre untrennbar.","Deutsche Universitäten basieren auf dem Prinzip der Einheit von Forschung und Lehre.","Das Bildungsideal Humboldts ist noch relevant, auch wenn der Alltag es herausfordert."],"correctAnswer":"Das Humboldtsche Bildungsideal, das Forschung und Lehre als untrennbare Einheit begreift, prägt noch heute das Selbstverständnis der deutschen Universitäten, auch wenn wirtschaftlicher Druck und Massenbetrieb es faktisch herausfordern."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der schnelle Ausbau erfolgte auf Kosten der ___.","options":["Qualität","Effizienz","Genauigkeit","Sorgfalt"],"correctAnswer":"Qualität"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The reform was pushed through at the cost of older employees","wordBankItems":["Die","Reform","wurde","auf","Kosten","der","älteren","Mitarbeiter","durchgesetzt","."],"correctAnswer":"Die Reform wurde auf Kosten der älteren Mitarbeiter durchgesetzt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Forschungsstark'' means?","options":["research-strong","research-intensive","academically strong","high-performing"],"correctAnswer":"research-strong"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000279',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss educational inequality at B2","Use Bildungsungleichheit vocabulary","Talk about social mobility and education in Germany"],"explanation":{"intro":"Educational inequality vocabulary covers social reproduction in education, intergenerational mobility, and reform approaches at B2.","culturalNote":"Bildungsungleichheit: Germany has high Bildungsvererbung (educational inheritance — education passes from parent to child). Key data: children of Akademiker (university graduates) 4× more likely to attend Gymnasium. PISA and IGLU reports show social background effect stronger in Germany than comparable nations. Key concepts: soziale Herkunft (social origin), Habitus (Bourdieu — unconscious social dispositions), Cultural Capital (kulturelles Kapital), Reproduktion sozialer Ungleichheit (social reproduction). Key policies: Kita-Ausbau (childcare expansion — early investment shown to reduce gaps), Ganztagsschule (full-day schooling — reduces informal resource effects), Sprachförderung."},"examples":[{"german":"Bildungsungleichheit in Deutschland ist besonders ausgeprägt, da frühe Selektion und die Bedeutung von kulturellem Kapital des Elternhauses dazu führen, dass Talente aus bildungsfernen Schichten strukturell benachteiligt werden.","english":"Educational inequality in Germany is particularly pronounced, as early selection and the significance of cultural capital of the parental home lead to talented individuals from educationally distant backgrounds being structurally disadvantaged."},{"german":"Soziale Mobilität durch Bildung setzt voraus, dass Schulen in der Lage sind, herkunftsbedingten Vorsprung auszugleichen — eine Anforderung, die das deutsche Schulsystem nach wie vor nur unzureichend erfüllt.","english":"Social mobility through education presupposes that schools are in a position to compensate for origin-based advantage — a requirement that the German school system still fulfils only insufficiently."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss educational inequality, social reproduction in German schools, and reform approaches at B2."}}',
'{"items":[{"word":"ausgeprägt","translation":"pronounced/marked","pronunciation":"OWS-geh-präkt","example":"Besonders ausgeprägt."},{"word":"bildungsfern","translation":"educationally distant","pronunciation":"BIL-doonks-fern","example":"Bildungsferne Schichten."},{"word":"benachteiligen","translation":"to disadvantage","pronunciation":"beh-NAKH-ty-li-gen","example":"Strukturell benachteiligen."},{"word":"die soziale Mobilität","translation":"social mobility","pronunciation":"dee zo-TSYAH-leh mo-bi-li-TÄT","example":"Soziale Mobilität."},{"word":"ausgleichen","translation":"to compensate/balance","pronunciation":"OWS-gly-khen","example":"Vorsprung ausgleichen."},{"word":"nach wie vor","translation":"still/as yet","pronunciation":"nakh vee for","example":"Nach wie vor unzureichend."}]}',
'{"title":"Nach wie vor — still, as yet (fixed adverbial: situation unchanged despite time)","pattern":"nach wie vor = still, as yet (literally: after as before — fixed phrase emphasising that a situation continues unchanged — often used when change was expected but didn''t happen)","explanation":"Nach wie vor = still, as yet (literally: after as before). Marks temporal persistence: Das System erfüllt die Anforderung nach wie vor nur unzureichend = The system still fulfils the requirement only insufficiently (expected to change, but hasn''t). More literary/formal than noch (still) — which is neutral. Nach wie vor implies the situation ought to have changed or should change. Compare: noch (still — neutral), immer noch (still — can be impatient), weiterhin (continues to — more forward-looking), bis heute (to this day — historical persistence), bis auf weiteres (until further notice — prospective).","examples":[{"sentence":"Das Problem besteht nach wie vor.","translation":"The problem still exists."},{"sentence":"Er ist nach wie vor der Beste auf seinem Gebiet.","translation":"He is still the best in his field."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Ausgeprägt'' means?","options":["pronounced/marked","distinct","strong","sharp"],"correctAnswer":"pronounced/marked"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Educational inequality in Germany is particularly pronounced, as early selection and the significance of cultural capital of the parental home lead to talented individuals from educationally distant backgrounds being structurally disadvantaged.","options":["Bildungsungleichheit in Deutschland ist besonders ausgeprägt, da frühe Selektion und die Bedeutung von kulturellem Kapital des Elternhauses dazu führen, dass Talente aus bildungsfernen Schichten strukturell benachteiligt werden.","In Deutschland hängt der Bildungserfolg stark von der sozialen Herkunft ab.","Wer aus einem bildungsfernen Elternhaus kommt, hat im deutschen Schulsystem schlechtere Chancen.","Das deutsche Schulsystem begünstigt Kinder aus Akademikerfamilien."],"correctAnswer":"Bildungsungleichheit in Deutschland ist besonders ausgeprägt, da frühe Selektion und die Bedeutung von kulturellem Kapital des Elternhauses dazu führen, dass Talente aus bildungsfernen Schichten strukturell benachteiligt werden."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Problem besteht nach wie ___.","options":["vor","wie","her","jetzt"],"correctAnswer":"vor"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He is still the best in his field","wordBankItems":["Er","ist","nach","wie","vor","der","Beste","auf","seinem","Gebiet","."],"correctAnswer":"Er ist nach wie vor der Beste auf seinem Gebiet ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Bildungsfern'' means?","options":["educationally distant","low-educated","disadvantaged","non-academic"],"correctAnswer":"educationally distant"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000027a',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss digital education at B2","Use Digitale Bildung vocabulary","Talk about EdTech, digital competences, and Germany''s digital divide"],"explanation":{"intro":"Digital education vocabulary covers digital literacy, e-learning, and the challenges of digitalising Germany''s schools at B2.","culturalNote":"Digitale Bildung: Digitalpakt Schule (Federal-State Digital Pact — 2019 — €5bn for hardware: tablets, interactive boards, Wi-Fi — criticised: money for hardware but not maintenance or training). Lehrerausbildung (teacher training — lagging digitally). Key concept: Medienkompetenz (media literacy — ability to critically evaluate digital media). KMK Bildungsstandards digital. International comparison: Estonia (Vorzeigemodell — model: e-school, coding from primary). Key risks: Algorithmen im Unterricht, Datenschutz, digitale Ablenkung. COVID: Schulen waren nicht auf Fernunterricht vorbereitet (not prepared for remote learning)."},"examples":[{"german":"Digitale Bildung erschöpft sich nicht in der Ausstattung von Schulen mit Endgeräten, sondern erfordert eine pädagogische Neuausrichtung, die digitale Werkzeuge lernförderlich integriert statt additiv einsetzt.","english":"Digital education is not exhausted in the equipping of schools with end devices, but requires a pedagogical reorientation that integrates digital tools in a learning-promoting way rather than deploying them additively."},{"german":"Der digitale Graben — die ungleiche Verfügbarkeit von Geräten, Internetzugang und digitalen Kompetenzen — verstärkt bestehende Bildungsungleichheiten, wenn digitale Bildung nicht gezielt gefördert wird.","english":"The digital divide — the unequal availability of devices, internet access, and digital competences — amplifies existing educational inequalities, when digital education is not purposefully promoted."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss digital education, media literacy, and Germany''s school digitalisation challenges at B2."}}',
'{"items":[{"word":"sich erschöpfen in","translation":"to be exhausted in / limited to","pronunciation":"zikh er-SHÖP-fen in","example":"Sich nicht in Hardware erschöpfen."},{"word":"die Ausstattung","translation":"equipping/equipment","pronunciation":"dee OWS-shtat-oong","example":"Ausstattung mit Endgeräten."},{"word":"lernförderlich","translation":"learning-promoting","pronunciation":"LERN-fö-der-likh","example":"Lernförderliche Integration."},{"word":"additiv","translation":"additive","pronunciation":"ah-di-TEEF","example":"Additiv einsetzen."},{"word":"der Graben","translation":"divide/gap","pronunciation":"dayr GRAH-ben","example":"Digitaler Graben."},{"word":"gezielt","translation":"purposefully/targeted","pronunciation":"geh-TSEELT","example":"Gezielt fördern."}]}',
'{"title":"Sich nicht in X erschöpfen — not to be limited to X, not to be merely about X","pattern":"etwas erschöpft sich nicht in X = something is not limited to X, is not exhausted by X (erschöpfen sich in = to be exhausted/contained in — implies: there is more to it than X)","explanation":"Sich in X erschöpfen = to be limited to X, to consist merely of X (erschöpfen = to exhaust; reflexive sich erschöpfen in = to exhaust itself in, i.e., to be entirely contained in/limited to). Digitale Bildung erschöpft sich nicht in der Ausstattung = Digital education is not limited to equipping (there is more to it). Used when rejecting an oversimplification: something is NOT merely X (a reductive view). Commonly used in academic/argumentative register. Compare: beschränken auf (to be limited to — often with lassen, kann man nicht beschränken auf), sich reduzieren auf (to be reduced to).","examples":[{"sentence":"Führung erschöpft sich nicht in Hierarchie.","translation":"Leadership is not limited to hierarchy."},{"sentence":"Kultur erschöpft sich nicht in Sprache.","translation":"Culture is not limited to language."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Gezielt'' means?","options":["purposefully/targeted","focused","specific","deliberate"],"correctAnswer":"purposefully/targeted"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Digital education is not exhausted in the equipping of schools with end devices, but requires a pedagogical reorientation that integrates digital tools in a learning-promoting way rather than deploying them additively.","options":["Digitale Bildung erschöpft sich nicht in der Ausstattung von Schulen mit Endgeräten, sondern erfordert eine pädagogische Neuausrichtung, die digitale Werkzeuge lernförderlich integriert statt additiv einsetzt.","Digitale Bildung braucht mehr als Tablets in Schulen.","Schulen brauchen nicht nur Hardware, sondern auch pädagogische Konzepte.","Digitale Bildung bedeutet, digitale Werkzeuge sinnvoll zu nutzen, nicht nur vorhanden zu haben."],"correctAnswer":"Digitale Bildung erschöpft sich nicht in der Ausstattung von Schulen mit Endgeräten, sondern erfordert eine pädagogische Neuausrichtung, die digitale Werkzeuge lernförderlich integriert statt additiv einsetzt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Führung erschöpft sich nicht in ___.","options":["Hierarchie","Autorität","Macht","Kontrolle"],"correctAnswer":"Hierarchie"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Culture is not limited to language","wordBankItems":["Kultur","erschöpft","sich","nicht","in","Sprache","."],"correctAnswer":"Kultur erschöpft sich nicht in Sprache ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Lernförderlich'' means?","options":["learning-promoting","educational","supportive","instructive"],"correctAnswer":"learning-promoting"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000027b',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss lifelong learning at B2","Use Lebenslanges Lernen vocabulary","Talk about adult education, reskilling, and continuing education"],"explanation":{"intro":"Lifelong learning vocabulary covers adult education, continuing professional development, and Germany''s Volkshochschule at B2.","culturalNote":"Lebenslanges Lernen: EU and German priority (Weiterbildungsgesetz). Key institutions: Volkshochschule (VHS — adult education centres, nationwide, low-cost — Germany-specific, remarkable institution), Berufsbegleitende Weiterbildung (continuing vocational training). Key concept: Qualifizierungsoffensive (qualification offensive — upskilling/reskilling for green and digital transformation). Kurzarbeit + Weiterbildung combination. Key debate: Wer soll bezahlen? (Who pays — employer, employee, state?). ILO: lifelong learning as human right. Recognition of prior learning (Anerkennung von Kompetenzen). Germany: Bildungsurlaub (education leave — statutory right to leave for learning in most Bundesländer)."},"examples":[{"german":"Lebenslanges Lernen ist in einer sich rasant verändernden Arbeitswelt keine bloße Empfehlung mehr, sondern eine strukturelle Notwendigkeit: Berufe wandeln sich, Qualifikationen veralten und neue Kompetenzen müssen kontinuierlich erworben werden.","english":"Lifelong learning is no longer a mere recommendation in a rapidly changing world of work, but a structural necessity: professions change, qualifications become outdated, and new competences must be continuously acquired."},{"german":"Die Volkshochschule ist ein einzigartiges deutsches Bildungsinstitut, das Weiterbildung zugänglich und bezahlbar hält und damit dem Ziel chancengleicher gesellschaftlicher Teilhabe dient.","english":"The Volkshochschule is a unique German educational institution that keeps continuing education accessible and affordable and thereby serves the goal of equal-opportunity societal participation."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss lifelong learning, Germany''s VHS, and reskilling for digital/green transformation at B2."}}',
'{"items":[{"word":"rasant","translation":"rapidly","pronunciation":"rah-ZANT","example":"Rasant verändernd."},{"word":"veralten","translation":"to become outdated","pronunciation":"fer-AL-ten","example":"Qualifikationen veralten."},{"word":"erwerben","translation":"to acquire","pronunciation":"er-VER-ben","example":"Kompetenzen erwerben."},{"word":"einzigartig","translation":"unique","pronunciation":"YN-tsikh-ar-tikh","example":"Einzigartiges Institut."},{"word":"zugänglich","translation":"accessible","pronunciation":"TSOO-gäng-likh","example":"Zugänglich halten."},{"word":"die Teilhabe","translation":"participation","pronunciation":"dee TYL-hah-beh","example":"Gesellschaftliche Teilhabe."}]}',
'{"title":"Keine bloße X mehr sein, sondern Y — no longer a mere X, but Y (upgrading a status)","pattern":"etwas ist keine bloße X mehr, sondern Y = something is no longer a mere X, but Y (bloß = mere — denotes insufficiency of X; mehr/no longer + sondern Y = but the stronger thing Y)","explanation":"Keine bloße X mehr, sondern Y = no longer a mere X, but Y. Bloß (mere) marks X as inadequate or insufficient (a soft version of the real status). Mehr (anymore) + negation marks that this was formerly so. Sondern Y introduces the stronger, more accurate status (Y > X). Ist keine bloße Empfehlung mehr, sondern eine strukturelle Notwendigkeit = is no longer a mere recommendation, but a structural necessity. This is a rhetorical upgrade: the old understanding (X) is rejected, the new correct understanding (Y) is installed. Compare: nicht einfach nur X, sondern Y (not simply X, but Y — similar but less of a status upgrade).","examples":[{"sentence":"Das ist kein bloßes Symptom mehr, sondern eine eigenständige Krise.","translation":"This is no longer a mere symptom, but an independent crisis."},{"sentence":"Klimaschutz ist keine bloße Option mehr, sondern eine Verpflichtung.","translation":"Climate protection is no longer a mere option, but an obligation."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Rasant'' means?","options":["rapidly","swiftly","briskly","speedily"],"correctAnswer":"rapidly"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Lifelong learning is no longer a mere recommendation in a rapidly changing world of work, but a structural necessity: professions change, qualifications become outdated, and new competences must be continuously acquired.","options":["Lebenslanges Lernen ist in einer sich rasant verändernden Arbeitswelt keine bloße Empfehlung mehr, sondern eine strukturelle Notwendigkeit: Berufe wandeln sich, Qualifikationen veralten und neue Kompetenzen müssen kontinuierlich erworben werden.","Im digitalen Zeitalter muss man ständig dazulernen.","Wer sich nicht weiterbildet, verliert den Anschluss am Arbeitsmarkt.","Lebenslanges Lernen ist wichtiger als je zuvor."],"correctAnswer":"Lebenslanges Lernen ist in einer sich rasant verändernden Arbeitswelt keine bloße Empfehlung mehr, sondern eine strukturelle Notwendigkeit: Berufe wandeln sich, Qualifikationen veralten und neue Kompetenzen müssen kontinuierlich erworben werden."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Klimaschutz ist keine bloße Option mehr, sondern eine ___.","options":["Verpflichtung","Notwendigkeit","Pflicht","Anforderung"],"correctAnswer":"Verpflichtung"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: This is no longer a mere symptom but an independent crisis","wordBankItems":["Das","ist","kein","bloßes","Symptom","mehr",",","sondern","eine","eigenständige","Krise","."],"correctAnswer":"Das ist kein bloßes Symptom mehr , sondern eine eigenständige Krise ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Zugänglich'' means?","options":["accessible","available","approachable","open"],"correctAnswer":"accessible"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000027c',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss language and identity at B2","Use Sprache und Identität vocabulary","Talk about language as identity, code-switching, and heritage languages"],"explanation":{"intro":"Language and identity vocabulary covers sociolinguistics, language as identity marker, and German language policy at B2.","culturalNote":"Sprache und Identität: Language is central to national identity (Hochdeutsch — standardised German, Herder on Volkssprache — folk language as national soul). Dialects (Dialekte — Bavarian, Saxon, Alemannic — marked social meanings). Code-switching (between languages/dialects). Heritage languages (Herkunftssprachen — Turkish, Russian, Arabic in Germany). Key: German as Amtssprache (official language — not constitutionally fixed until Bavarian constitution, no federal constitutional status). Sprachenpolitik (language policy). Goethe-Institut (German cultural/language promotion globally). German speakers: 95M native speakers, major European language."},"examples":[{"german":"Sprache ist nicht nur Kommunikationsmittel, sondern ein konstitutives Element von Identität: Sie formt Zugehörigkeitsgefühle, markiert soziale Grenzen und trägt kollektive Gedächtnisse kultureller Gruppen.","english":"Language is not only a means of communication, but a constitutive element of identity: it shapes feelings of belonging, marks social boundaries, and carries the collective memories of cultural groups."},{"german":"Mehrsprachig aufgewachsene Menschen navigieren täglich zwischen sprachlichen Welten — ein Repertoire, das kognitive Flexibilität fördert, gesellschaftlich aber oft als Defizit statt als Ressource wahrgenommen wird.","english":"People who grew up multilingually navigate daily between linguistic worlds — a repertoire that promotes cognitive flexibility, but that is often socially perceived as a deficit rather than a resource."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss language as identity, heritage languages, and code-switching in Germany at B2."}}',
'{"items":[{"word":"konstitutiv","translation":"constitutive","pronunciation":"kon-sti-too-TEEF","example":"Konstitutives Element."},{"word":"das Zugehörigkeitsgefühl","translation":"sense of belonging","pronunciation":"dahs tsoo-geh-HÖ-rikh-kyts-geh-fühl","example":"Zugehörigkeitsgefühle."},{"word":"markieren","translation":"to mark","pronunciation":"mar-KEER-en","example":"Soziale Grenzen markieren."},{"word":"navigieren","translation":"to navigate","pronunciation":"nah-vi-GEER-en","example":"Zwischen Welten navigieren."},{"word":"kognitiv","translation":"cognitive","pronunciation":"kog-ni-TEEF","example":"Kognitive Flexibilität."},{"word":"wahrnehmen als","translation":"to perceive as","pronunciation":"VAR-nay-men als","example":"Als Defizit wahrnehmen."}]}',
'{"title":"Als X statt als Y wahrgenommen werden — perceived as X rather than as Y","pattern":"etwas wird als X statt als Y wahrgenommen = something is perceived as X rather than as Y (statt als here = rather than as — marks the preferred/correct perception Y that is not happening)","explanation":"Als X statt als Y wahrgenommen werden = to be perceived as X rather than (as) Y. Als Defizit statt als Ressource wahrgenommen = perceived as a deficit rather than a resource (the actual situation is X — deficit — while Y — resource — would be the correct/preferred framing). Statt als = instead of as (statt + als, the als marks the categorical alternative). In formal writing: als X, nicht als Y (more symmetric). This construction is common in sociolinguistic and educational discourse to critique misperceptions.","examples":[{"sentence":"Kritik wird oft als Angriff statt als Verbesserungsversuch wahrgenommen.","translation":"Criticism is often perceived as an attack rather than as an attempt at improvement."},{"sentence":"Fehler sollten als Lernchance statt als Versagen wahrgenommen werden.","translation":"Mistakes should be perceived as a learning opportunity rather than as failure."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Konstitutiv'' means?","options":["constitutive","essential","foundational","defining"],"correctAnswer":"constitutive"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Language is not only a means of communication, but a constitutive element of identity: it shapes feelings of belonging, marks social boundaries, and carries the collective memories of cultural groups.","options":["Sprache ist nicht nur Kommunikationsmittel, sondern ein konstitutives Element von Identität: Sie formt Zugehörigkeitsgefühle, markiert soziale Grenzen und trägt kollektive Gedächtnisse kultureller Gruppen.","Sprache verbindet Menschen und formt ihre Identität.","Identität und Sprache sind eng miteinander verbunden.","Über Sprache definieren wir uns und unsere kulturelle Zugehörigkeit."],"correctAnswer":"Sprache ist nicht nur Kommunikationsmittel, sondern ein konstitutives Element von Identität: Sie formt Zugehörigkeitsgefühle, markiert soziale Grenzen und trägt kollektive Gedächtnisse kultureller Gruppen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Kritik wird oft als Angriff statt als Verbesserungsversuch ___.","options":["wahrgenommen","gesehen","empfunden","angesehen"],"correctAnswer":"wahrgenommen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Mistakes should be perceived as a learning opportunity rather than as failure","wordBankItems":["Fehler","sollten","als","Lernchance","statt","als","Versagen","wahrgenommen","werden","."],"correctAnswer":"Fehler sollten als Lernchance statt als Versagen wahrgenommen werden ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Zugehörigkeitsgefühl'' means?","options":["sense of belonging","feeling of membership","attachment","community feeling"],"correctAnswer":"sense of belonging"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000027d',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss multilingualism at B2","Use Mehrsprachigkeit vocabulary","Talk about bilingualism, language policy, and European multilingualism"],"explanation":{"intro":"Multilingualism vocabulary covers bilingual education, European language policy, and cognitive advantages of multilingualism at B2.","culturalNote":"Mehrsprachigkeit: EU: 24 official languages, 60+ regional and minority languages. European language policy: mother tongue + 2 foreign languages. Germany: Sprachenpolitik — Deutsch + English + one other language (Spanish, French, Mandarin). Privilegierte Sprachen vs. Minderheitensprachen (minority languages — Sorbian, Frisian, Danish, Romani, Low German). Bilingual schools (Zweisprachige Schulen). Cognitive advantages of multilingualism (Bilingualismus Forschung — executive function, metalinguistic awareness, possibly delayed Alzheimer). Immigration: Herkunftssprachen. Translanguaging (crossing between languages fluidly)."},"examples":[{"german":"Mehrsprachigkeit wird zunehmend als kognitiver und kultureller Vorteil anerkannt statt als kommunikative Belastung betrachtet — eine Verschiebung im Selbstverständnis europäischer Bildungssysteme.","english":"Multilingualism is increasingly being recognised as a cognitive and cultural advantage rather than being regarded as a communicative burden — a shift in the self-understanding of European education systems."},{"german":"Die Sprachenpolitik der EU sieht die Förderung von Mehrsprachigkeit als Instrument zur kulturellen Integration und wirtschaftlichen Wettbewerbsfähigkeit, steht aber in einem Spannungsverhältnis zu den dominierenden Funktionen des Englischen.","english":"EU language policy views the promotion of multilingualism as an instrument for cultural integration and economic competitiveness, but stands in tension with the dominant functions of English."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss multilingualism, EU language policy, and cognitive advantages of bilingualism at B2."}}',
'{"items":[{"word":"anerkennen","translation":"to recognise/acknowledge","pronunciation":"AN-er-ken-en","example":"Als Vorteil anerkennen."},{"word":"zunehmend","translation":"increasingly","pronunciation":"TSOO-nay-mend","example":"Zunehmend anerkannt."},{"word":"die Verschiebung","translation":"shift","pronunciation":"dee fer-SHEE-boong","example":"Verschiebung im Selbstverständnis."},{"word":"die Wettbewerbsfähigkeit","translation":"competitiveness","pronunciation":"dee VET-beh-verbs-fä-ikh-kyt","example":"Wirtschaftliche Wettbewerbsfähigkeit."},{"word":"dominierend","translation":"dominant","pronunciation":"do-mi-NEER-end","example":"Dominierende Funktion des Englischen."},{"word":"das Instrument","translation":"instrument/tool","pronunciation":"dahs in-stroo-MENT","example":"Als Instrument zur Integration."}]}',
'{"title":"Als X anerkannt werden statt als Y betrachtet werden — recognised as X rather than regarded as Y","pattern":"als X anerkannt werden statt als Y betrachtet werden = to be recognised as X rather than regarded as Y (contrast between two evaluative stances — recognition vs. (incorrect) characterisation)","explanation":"Als X anerkannt werden (to be recognised as X) vs. als Y betrachtet werden (to be regarded as Y): the statt als Y construction marks the rejected/incorrect prior stance. Mehrsprachigkeit wird als Vorteil anerkannt statt als Belastung betrachtet = Multilingualism is recognised as an advantage rather than being regarded as a burden. This is a variant of the als X statt als Y pattern: two parallel passive constructions with different verbs (anerkennen vs. betrachten). Anerkennen (to recognise/acknowledge — more positive evaluation) vs. betrachten (to regard — neutral or more negative here). The statt marks the old/wrong perception being replaced.","examples":[{"sentence":"Diversität wird als Stärke anerkannt statt als Problem betrachtet.","translation":"Diversity is recognised as a strength rather than regarded as a problem."},{"sentence":"Die Initiative wird als Durchbruch gefeiert statt als bloße Symbolpolitik abgetan.","translation":"The initiative is celebrated as a breakthrough rather than dismissed as mere symbolic politics."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Zunehmend'' means?","options":["increasingly","progressively","growing","more and more"],"correctAnswer":"increasingly"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Multilingualism is increasingly being recognised as a cognitive and cultural advantage rather than being regarded as a communicative burden — a shift in the self-understanding of European education systems.","options":["Mehrsprachigkeit wird zunehmend als kognitiver und kultureller Vorteil anerkannt statt als kommunikative Belastung betrachtet — eine Verschiebung im Selbstverständnis europäischer Bildungssysteme.","Mehrsprachigkeit hat Vorteile, wird aber oft nicht als solche anerkannt.","Die Einstellung zu Mehrsprachigkeit in Europa wandelt sich.","Mehrsprachigkeit gilt heute als Vorteil, nicht mehr als Nachteil."],"correctAnswer":"Mehrsprachigkeit wird zunehmend als kognitiver und kultureller Vorteil anerkannt statt als kommunikative Belastung betrachtet — eine Verschiebung im Selbstverständnis europäischer Bildungssysteme."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Diversität wird als Stärke anerkannt statt als Problem ___.","options":["betrachtet","gesehen","eingestuft","empfunden"],"correctAnswer":"betrachtet"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The initiative is celebrated as a breakthrough rather than dismissed as mere symbolic politics","wordBankItems":["Die","Initiative","wird","als","Durchbruch","gefeiert","statt","als","bloße","Symbolpolitik","abgetan","."],"correctAnswer":"Die Initiative wird als Durchbruch gefeiert statt als bloße Symbolpolitik abgetan ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Verschiebung'' means?","options":["shift","change","transition","movement"],"correctAnswer":"shift"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000027e',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss media and society at B2","Use Medien und Gesellschaft vocabulary","Talk about media functions, public broadcasting, and press freedom"],"explanation":{"intro":"Media and society vocabulary covers the functions of media, press freedom, and Germany''s public broadcasting system at B2.","culturalNote":"Medien und Gesellschaft: Germany: duales Rundfunksystem (dual broadcasting system — öffentlich-rechtlich/public broadcasters: ARD, ZDF, Deutschlandradio + private). ARD/ZDF funded by Rundfunkbeitrag (broadcasting contribution — per household). Pressefreiheit (press freedom — guaranteed Artikel 5 GG). Germany: Spiegel (founded 1947 — established investigative journalism tradition), Spiegel-Affäre (1962 — crucial for press freedom). Key concepts: Vierte Gewalt (fourth estate — watchdog function), agenda-setting (Medien setzen Themen), Qualitätsjournalismus (quality journalism). Challenges: Reichweitenverlust Qualitätsmedien (losing reach), lokale Erosion (Lokalzeitungen sterben), Populismus und Lügenpresse (Lügenpresse-Ruf — fake news accusations)."},"examples":[{"german":"Die Medien übernehmen in demokratischen Gesellschaften eine fundamentale Kontrollfunktion: Sie decken Missstände auf, machen Macht transparent und ermöglichen informierte politische Partizipation — Voraussetzungen, die einen geschützten, unabhängigen Journalismus erfordern.","english":"The media take on a fundamental oversight function in democratic societies: they expose grievances, make power transparent, and enable informed political participation — prerequisites that require a protected, independent journalism."},{"german":"Der öffentlich-rechtliche Rundfunk in Deutschland genießt laut Verfassungsgericht einen besonderen staatsfernfreien Status, der seiner gesellschaftlichen Integrationsfunktion Rechnung trägt.","english":"Public broadcasting in Germany enjoys, according to the Constitutional Court, a special status free from state influence, which takes account of its societal integration function."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss media functions, Germany''s public broadcasting, and press freedom at B2."}}',
'{"items":[{"word":"die Kontrollfunktion","translation":"oversight function","pronunciation":"dee kon-TROL-funk-tsyohn","example":"Fundamentale Kontrollfunktion."},{"word":"aufdecken","translation":"to expose/uncover","pronunciation":"OWF-dek-en","example":"Missstände aufdecken."},{"word":"der Missstand","translation":"grievance/abuse","pronunciation":"dayr MIS-shtant","example":"Missstände aufdecken."},{"word":"Rechnung tragen","translation":"to take account of","pronunciation":"REKh-noong TRAH-gen","example":"Einer Funktion Rechnung tragen."},{"word":"staatsfernfrei","translation":"free from state influence","pronunciation":"SHTAHTS-fern-fry","example":"Staatsfernfreier Status."},{"word":"informiert","translation":"informed","pronunciation":"in-for-MEERT","example":"Informierte Partizipation."}]}',
'{"title":"Einer Sache Rechnung tragen — to take account of something (formal recognition)","pattern":"etwas trägt einer Sache Rechnung = something takes account of something, makes allowance for something (Rechnung tragen = fixed phrase — formal; dative)","explanation":"Einer Sache Rechnung tragen = to take account of something, to make allowance for something (trägt Rechnung — separable: trägt...Rechnung). Fixed formal/administrative phrase. Der Status trägt der Integrationsfunktion Rechnung = The status takes account of/recognises the integration function. Einem Umstand/einer Tatsache/einem Bedürfnis Rechnung tragen (to take account of a circumstance/fact/need). Compare: berücksichtigen (to take into account — more general), beachten (to observe/heed), in Betracht ziehen (to consider). Rechnung tragen is specifically: the design/decision explicitly accounts for something.","examples":[{"sentence":"Die Lösung muss der Komplexität der Situation Rechnung tragen.","translation":"The solution must take account of the complexity of the situation."},{"sentence":"Das Gesetz trägt neuen technologischen Entwicklungen Rechnung.","translation":"The law takes account of new technological developments."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Missstand'' means?","options":["grievance/abuse","problem","malfunction","deficiency"],"correctAnswer":"grievance/abuse"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The media take on a fundamental oversight function in democratic societies: they expose grievances, make power transparent, and enable informed political participation — prerequisites that require a protected, independent journalism.","options":["Die Medien übernehmen in demokratischen Gesellschaften eine fundamentale Kontrollfunktion: Sie decken Missstände auf, machen Macht transparent und ermöglichen informierte politische Partizipation — Voraussetzungen, die einen geschützten, unabhängigen Journalismus erfordern.","Freie Medien sind eine Grundvoraussetzung für Demokratie.","Medien müssen unabhängig sein, um ihrer demokratischen Funktion gerecht zu werden.","Die Presse kontrolliert politische Macht und informiert Bürger."],"correctAnswer":"Die Medien übernehmen in demokratischen Gesellschaften eine fundamentale Kontrollfunktion: Sie decken Missstände auf, machen Macht transparent und ermöglichen informierte politische Partizipation — Voraussetzungen, die einen geschützten, unabhängigen Journalismus erfordern."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Lösung muss der Komplexität der Situation Rechnung ___.","options":["tragen","nehmen","geben","halten"],"correctAnswer":"tragen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The law takes account of new technological developments","wordBankItems":["Das","Gesetz","trägt","neuen","technologischen","Entwicklungen","Rechnung","."],"correctAnswer":"Das Gesetz trägt neuen technologischen Entwicklungen Rechnung ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Aufdecken'' means?","options":["to expose/uncover","to reveal","to disclose","to unearth"],"correctAnswer":"to expose/uncover"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000027f',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the digital public sphere at B2","Use Digitale Öffentlichkeit vocabulary","Talk about social media, filter bubbles, and democratic discourse"],"explanation":{"intro":"Digital public sphere vocabulary covers the transformation of the public sphere through social media, algorithmic filtering, and polarisation at B2.","culturalNote":"Digitale Öffentlichkeit: Habermas: Öffentlichkeit (public sphere — rational discourse, foundation of democracy). Digital transformation: social media platforms (Facebook, Twitter/X, TikTok, Instagram) as new public sphere — but with algorithmic curation (Algorithmen bevorzugen Engagement, nicht Qualität). Filter bubble (Filterblase — Echo-Kammer — exposure only to confirming views). Polarisierung (polarisation). NetzDG (Netzwerkdurchsetzungsgesetz — German law requiring platforms to delete illegal content — controversial but influential model globally). EU: Digital Services Act (DSA — stronger regulation). Key tension: Meinungsfreiheit (free speech) vs. Plattformregulierung (platform regulation)."},"examples":[{"german":"Digitale Plattformen haben die Öffentlichkeit in gewisser Weise pluralisiert — geben aber gleichzeitig algorithmisch kuratierten Informationsblasen Vorschub, die einen gemeinsamen Faktenkonsens als Grundlage demokratischen Diskurses untergraben.","english":"Digital platforms have pluralised the public sphere in a certain sense — but at the same time give impetus to algorithmically curated information bubbles that undermine a shared factual consensus as the foundation of democratic discourse."},{"german":"Die Debatte um Plattformregulierung dreht sich um einen fundamentalen Spannungsraum: Soll der Staat in die Inhaltemoderation eingreifen, um demokratische Diskurse zu schützen, oder würde dies den Ausnahmecharakter staatlicher Zensur normalisieren?","english":"The debate about platform regulation revolves around a fundamental space of tension: should the state intervene in content moderation to protect democratic discourses, or would this normalise the exceptional character of state censorship?"}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss digital public spheres, filter bubbles, and platform regulation at B2."}}',
'{"items":[{"word":"pluralisieren","translation":"to pluralise","pronunciation":"ploo-rah-li-ZEER-en","example":"Öffentlichkeit pluralisiert."},{"word":"Vorschub leisten","translation":"to give impetus to/abet","pronunciation":"FOR-shoob LYS-ten","example":"Blasen Vorschub leisten."},{"word":"der Faktenkonsens","translation":"factual consensus","pronunciation":"dayr FAK-ten-kon-zens","example":"Gemeinsamer Faktenkonsens."},{"word":"untergraben","translation":"to undermine","pronunciation":"oon-ter-GRAH-ben","example":"Konsens untergraben."},{"word":"eingreifen in","translation":"to intervene in","pronunciation":"YN-gry-fen in","example":"In Moderation eingreifen."},{"word":"normalisieren","translation":"to normalise","pronunciation":"nor-mah-li-ZEER-en","example":"Etwas normalisieren."}]}',
'{"title":"Etwas (einer Sache) Vorschub leisten — to give impetus to / to abet something","pattern":"etwas leistet einer Sache Vorschub = something gives impetus to something, abets/fosters something (Vorschub leisten + dative — formal; the subject inadvertently enables or actively promotes X)","explanation":"Einer Sache Vorschub leisten = to give impetus to something, to abet, to facilitate (often unintentional or undesirable). Informationsblasen Vorschub leisten = to give impetus to information bubbles (the platforms enable/foster the bubbles). Formal/written register — not everyday speech. Dative: Vorschub leisten + wem/was = dative. Compare: begünstigen (to promote/favour — more neutral), fördern (to support/promote — positive), befördern (to advance — less critical). Vorschub leisten has a connotation of enabling something problematic.","examples":[{"sentence":"Armut leistet sozialer Ausgrenzung Vorschub.","translation":"Poverty gives impetus to social exclusion."},{"sentence":"Populistische Rhetorik leistet der Spaltung Vorschub.","translation":"Populist rhetoric abets division."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Untergraben'' means?","options":["to undermine","to erode","to subvert","to weaken"],"correctAnswer":"to undermine"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Digital platforms have pluralised the public sphere in a certain sense — but at the same time give impetus to algorithmically curated information bubbles that undermine a shared factual consensus as the foundation of democratic discourse.","options":["Digitale Plattformen haben die Öffentlichkeit in gewisser Weise pluralisiert — geben aber gleichzeitig algorithmisch kuratierten Informationsblasen Vorschub, die einen gemeinsamen Faktenkonsens als Grundlage demokratischen Diskurses untergraben.","Soziale Medien zersplittern die Öffentlichkeit in Filterblasen.","Digitale Plattformen ermöglichen mehr Vielfalt, fördern aber auch Echokammern.","Algorithmen verstärken Filterblasen und gefährden den öffentlichen Diskurs."],"correctAnswer":"Digitale Plattformen haben die Öffentlichkeit in gewisser Weise pluralisiert — geben aber gleichzeitig algorithmisch kuratierten Informationsblasen Vorschub, die einen gemeinsamen Faktenkonsens als Grundlage demokratischen Diskurses untergraben."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Populistische Rhetorik leistet der Spaltung ___.","options":["Vorschub","Auftrieb","Förderung","Unterstützung"],"correctAnswer":"Vorschub"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Poverty gives impetus to social exclusion","wordBankItems":["Armut","leistet","sozialer","Ausgrenzung","Vorschub","."],"correctAnswer":"Armut leistet sozialer Ausgrenzung Vorschub ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Normalisieren'' means?","options":["to normalise","to standardise","to regularise","to make normal"],"correctAnswer":"to normalise"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000280',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss disinformation at B2","Use Desinformation vocabulary","Talk about fake news, media literacy, and combating disinformation"],"explanation":{"intro":"Disinformation vocabulary covers fake news, propaganda, and strategies for combating information manipulation at B2.","culturalNote":"Desinformation: Key distinctions: Misinformation (false info without intent to deceive), Disinformation (false with intent), Malinformation (true but weaponised). Germany: experiences: Russian disinformation campaigns (Ukraine, COVID vaccines), far-right networks. Bundesamt für Verfassungsschutz (BfV — domestic intelligence — monitors disinformation). BpB (Bundeszentrale für politische Bildung — Civic Education Agency — key counter-narrative publisher). EU: Strengthened Code of Practice on Disinformation (2022). Key detection: Fact-checking (Correctiv, dpa Faktencheck). Deep Fakes. Social media amplification. Critical concept: Epistemic crisis (shared truth becoming harder to maintain)."},"examples":[{"german":"Desinformation ist keine neue Erscheinung — politische Propaganda und Gerüchte existieren seit Jahrtausenden — aber digitale Plattformen haben ihr Ausbreitungstempo und ihre Reichweite fundamental verändert.","english":"Disinformation is not a new phenomenon — political propaganda and rumours have existed for thousands of years — but digital platforms have fundamentally changed its speed of spread and reach."},{"german":"Faktenkompetenz — die Fähigkeit, Quellen kritisch zu bewerten und Desinformation zu erkennen — wird in der digitalen Informationsumgebung zur Schlüsselqualifikation demokratischer Bürgerschaft.","english":"Fact literacy — the ability to critically evaluate sources and recognise disinformation — becomes a key qualification of democratic citizenship in the digital information environment."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss disinformation, fake news, and fact literacy as democratic skills at B2."}}',
'{"items":[{"word":"die Erscheinung","translation":"phenomenon","pronunciation":"dee er-SHY-noong","example":"Keine neue Erscheinung."},{"word":"das Ausbreitungstempo","translation":"speed of spread","pronunciation":"dahs OWS-bry-toonks-tem-po","example":"Ausbreitungstempo verändert."},{"word":"die Reichweite","translation":"reach","pronunciation":"dee RYKH-vy-teh","example":"Reichweite verändert."},{"word":"bewerten","translation":"to evaluate","pronunciation":"beh-VER-ten","example":"Quellen kritisch bewerten."},{"word":"die Faktenkompetenz","translation":"fact literacy","pronunciation":"dee FAK-ten-kom-peh-tents","example":"Faktenkompetenz aufbauen."},{"word":"die Bürgerschaft","translation":"citizenship","pronunciation":"dee BÜR-ger-shaft","example":"Demokratische Bürgerschaft."}]}',
'{"title":"Zur Schlüsselqualifikation werden — to become a key qualification (evolving status)","pattern":"etwas wird zur Schlüsselqualifikation = something becomes a key qualification (werden + zu + dative noun — to become; zur = zu + der; describes status transition)","explanation":"Werden + zu + dative = to become (transition to a new status). Faktenkompetenz wird zur Schlüsselqualifikation = Fact literacy becomes a key qualification (zur = zu + der — dative feminine). Werden zu marks a transition or transformation: what something turns into. Ich werde Arzt (nominative — professions), but werden zu + noun (with article) for broader transformations. Compare: sich entwickeln zu (to develop into — more gradual), sich wandeln zu (to transform into — more radical), sich entpuppen als (to turn out to be — revealing a true nature). Werden zu is the most neutral transition.","examples":[{"sentence":"Der Protest wurde zur Bewegung.","translation":"The protest became a movement."},{"sentence":"Die Ausnahme wird zur Norm.","translation":"The exception becomes the norm."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Reichweite'' means?","options":["reach","range","scope","coverage"],"correctAnswer":"reach"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Disinformation is not a new phenomenon — political propaganda and rumours have existed for thousands of years — but digital platforms have fundamentally changed its speed of spread and reach.","options":["Desinformation ist keine neue Erscheinung — politische Propaganda und Gerüchte existieren seit Jahrtausenden — aber digitale Plattformen haben ihr Ausbreitungstempo und ihre Reichweite fundamental verändert.","Desinformation ist nicht neu, aber digitale Verbreitung macht sie gefährlicher.","Fake News existierten schon immer, nehmen aber durch soziale Medien zu.","Digitale Medien ermöglichen schnelle Verbreitung von Fehlinformationen."],"correctAnswer":"Desinformation ist keine neue Erscheinung — politische Propaganda und Gerüchte existieren seit Jahrtausenden — aber digitale Plattformen haben ihr Ausbreitungstempo und ihre Reichweite fundamental verändert."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Ausnahme wird zur ___.","options":["Norm","Regel","Gewohnheit","Praxis"],"correctAnswer":"Norm"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The protest became a movement","wordBankItems":["Der","Protest","wurde","zur","Bewegung","."],"correctAnswer":"Der Protest wurde zur Bewegung ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Faktenkompetenz'' means?","options":["fact literacy","fact-checking","media literacy","critical thinking"],"correctAnswer":"fact literacy"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

